import json, os, re, sys, collections
root = '/Users/gabe/.claude/projects'
pat = re.compile(r'(pages|orin-dx-site|callisto|caliper|monokl)', re.I)
types = ['muse:exit-gate','scribe:exit-gate','muse:auditor','scribe:auditor','scribe:verifier','navigator:challenger','smith:reviewer','smith:mutator','smith:exit-gate','ranger:adversary','sentinel:exit-gate','sentinel:verifier']
out = open(os.path.join(os.environ['TMPDIR'], 'index.tsv'), 'w')
cnt = collections.Counter()
files = 0
for d in sorted(os.listdir(root)):
    if not pat.search(d): continue
    dp = os.path.join(root, d)
    for dirpath, dn, fn in os.walk(dp):
        for f in fn:
            if not f.endswith('.jsonl'): continue
            p = os.path.join(dirpath, f)
            files += 1
            try:
                with open(p, errors='replace') as fh:
                    for ln, line in enumerate(fh):
                        if '"subagent_type"' not in line: continue
                        for t in types:
                            if ('"subagent_type":"%s"' % t) in line:
                                cnt[(d, t)] += 1
                                out.write('\t'.join([d, p, str(ln), t]) + '\n')
            except Exception as e:
                print('ERR', p, e)
print('files', files)
bytype = collections.Counter()
for (d, t), c in cnt.items(): bytype[t] += c
print(bytype)
byproj = collections.defaultdict(collections.Counter)
for (d, t), c in cnt.items():
    byproj[re.sub(r'--claude-worktrees-.*', '', d)][t] += c
for k, v in byproj.items(): print(k, dict(v))

