import json,sys,glob,os,collections,re
base=os.path.expanduser('~/.claude/projects')
rows=[]
PL=('courier','mason','muse','navigator','ranger','scribe','sentinel','smith','vanguard','weaver')
for d in sorted(os.listdir(base)):
    if not re.search(r'orin-dx|Projects-pages',d): continue
    for f in glob.glob(f'{base}/{d}/**/*.jsonl',recursive=True):
        sk=collections.Counter();ag=collections.Counter();nmsg=0;first=None;last=None;title=None
        try:
            for line in open(f,errors='ignore'):
                try:o=json.loads(line)
                except:continue
                nmsg+=1
                ts=o.get('timestamp')
                if ts:
                    first=first or ts;last=ts
                m=o.get('message')
                if isinstance(m,dict) and isinstance(m.get('content'),list):
                    for c in m['content']:
                        if c.get('type')=='tool_use':
                            i=c.get('input',{})
                            if c['name']=='Skill': sk[i.get('skill')]+=1
                            elif c['name'] in('Agent','Task'): ag[i.get('subagent_type')]+=1
        except Exception as e: pass
        rows.append(dict(dir=d,file=f,n=nmsg,first=first,last=last,skills=dict(sk),agents=dict(ag),sub='/subagents/' in f))
json.dump(rows,open(sys.argv[1],'w'))
tot=collections.Counter();tota=collections.Counter()
for r in rows:
    for k,v in r['skills'].items():tot[(r['dir'][-25:],k)]+=v
    for k,v in r['agents'].items():tota[(r['dir'][-25:],k)]+=v
print('files',len(rows))
for k,v in sorted(tot.items(),key=lambda x:-x[1])[:70]:print('SKILL',k,v)
for k,v in sorted(tota.items(),key=lambda x:-x[1])[:50]:print('AGENT',k,v)

