import json, os, sys, collections
tmp = os.environ['TMPDIR']
rows = [l.rstrip('\n').split('\t') for l in open(os.path.join(tmp, 'index.tsv'))]
byfile = collections.defaultdict(list)
for d, p, ln, t in rows: byfile[p].append((int(ln), t, d))
res = []
for p, items in byfile.items():
    uses = {}
    results = {}
    with open(p, errors='replace') as fh:
        for ln, line in enumerate(fh):
            if '"tool_use_id"' not in line and '"subagent_type"' not in line: continue
            try: j = json.loads(line)
            except Exception: continue
            msg = j.get('message', {})
            c = msg.get('content')
            if not isinstance(c, list): continue
            for b in c:
                if b.get('type') == 'tool_use' and b.get('name') in ('Agent', 'Task'):
                    st = b.get('input', {}).get('subagent_type')
                    uses[b['id']] = (ln, st, b['input'], j.get('timestamp'))
                elif b.get('type') == 'tool_result':
                    results[b['tool_use_id']] = (ln, b.get('content'), j.get('toolUseResult'), j.get('timestamp'))
    for tid, (ln, st, inp, ts) in uses.items():
        if st not in ('ranger:adversary','muse:exit-gate','scribe:exit-gate','muse:auditor','scribe:auditor','scribe:verifier','navigator:challenger'): continue
        r = results.get(tid)
        txt = ''
        meta = {}
        if r:
            c = r[1]
            if isinstance(c, list): txt = '\n'.join(x.get('text', '') for x in c if isinstance(x, dict))
            else: txt = str(c)
            tur = r[2]
            if isinstance(tur, dict):
                meta = {k: tur.get(k) for k in ('totalTokens', 'totalDurationMs', 'totalToolUseCount') if k in tur}
        res.append(dict(file=p, proj=p.split('/')[5], st=st, ts=ts, desc=inp.get('description'), prompt=inp.get('prompt', ''), result=txt, meta=meta, rts=r[3] if r else None))
res.sort(key=lambda x: (x['proj'], x['ts'] or ''))
json.dump(res, open(os.path.join(tmp, 'runs.json'), 'w'))
print(len(res))
c = collections.Counter((r['proj'].split('--')[0], r['st'], bool(r['meta'])) for r in res)
for k, v in sorted(c.items()): print(k, v)

