for dirpath, dn, fn in os.walk(root):
    for f in fn:
        if f.startswith('agent-') and f.endswith('.jsonl'):
            idx.setdefault(f[6:-6], []).append(os.path.join(dirpath, f))
def analyze(path):
    toks_in = toks_out = cache_r = 0; calls = 0; last = ''; tools = 0; t0 = t1 = None
    with open(path, errors='replace') as fh:
        for line in fh:
            try: j = json.loads(line)
            except Exception: continue
            ts = j.get('timestamp')
            if ts:
                t0 = t0 or ts; t1 = ts
            m = j.get('message', {})
            if m.get('role') == 'assistant':
                u = m.get('usage', {})
                toks_in += u.get('input_tokens', 0) + u.get('cache_creation_input_tokens', 0)
                cache_r += u.get('cache_read_input_tokens', 0)
                toks_out += u.get('output_tokens', 0)
                calls += 1
                c = m.get('content')
                if isinstance(c, list):
                    for b in c:
                        if b.get('type') == 'text' and b.get('text', '').strip(): last = b['text']
                        if b.get('type') == 'tool_use': tools += 1
    return dict(calls=calls, tools=tools, in_new=toks_in, cache_read=cache_r, out=toks_out, last=last, t0=t0, t1=t1)
n = 0
for r in res:
