import json, os, re, collections
from datetime import datetime
tmp = os.environ['TMPDIR']
root = '/Users/gabe/.claude/projects'
pat = re.compile(r'(Projects-pages$|Projects-callisto$|Projects-monokl$|Projects-caliper$|orin-dx-site)')
types = ['lambda:lambda-reviewer','lambda:reviewer','lambda:lambda-exit-gate','lambda:exit-gate','lambda:lambda-mutator','lambda:mutator','vector:vector-challenger','vector:challenger','canon:canon-exit-gate','canon:exit-gate','canon:canon-auditor','canon:auditor','canon:canon-verifier','canon:verifier','canon-verifier','axiom:axiom-exit-gate','axiom:axiom-verifier','smith:reviewer','smith:mutator','smith:exit-gate','sentinel:exit-gate','sentinel:verifier']
tset = set(types)
agentfiles = collections.defaultdict(list)
runs = {}
for d in sorted(os.listdir(root)):
    if not pat.search(d): continue
    for dp, dn, fn in os.walk(os.path.join(root, d)):
        for f in fn:
            p = os.path.join(dp, f)
            if f.startswith('agent-') and f.endswith('.jsonl'):
                agentfiles[d].append(p); continue
            if not f.endswith('.jsonl'): continue
            uses = {}; results = {}
            for line in open(p, errors='replace'):
                if '"subagent_type"' in line and any(('"subagent_type":"%s"' % t) in line for t in tset):
                    try: j = json.loads(line)
                    except Exception: continue
                    c = j.get('message', {}).get('content')
                    if isinstance(c, list):
                        for b in c:
                            if b.get('type') == 'tool_use' and b.get('input', {}).get('subagent_type') in tset:
                                uses[b['id']] = (b['input'], j.get('timestamp'))
                elif '"tool_result"' in line and uses:
                    try: j = json.loads(line)
                    except Exception: continue
                    c = j.get('message', {}).get('content')
                    if isinstance(c, list):
                        for b in c:
                            if b.get('type') == 'tool_result' and b.get('tool_use_id') in uses:
                                cc = b.get('content')
                                results[b['tool_use_id']] = '\n'.join(x.get('text', '') for x in cc if isinstance(x, dict)) if isinstance(cc, list) else str(cc)
            for tid, (inp, ts) in uses.items():
                runs[tid] = dict(proj=d, file=p, st=inp['subagent_type'], ts=ts, desc=inp.get('description'), prompt=inp.get('prompt', '')[:600], result=results.get(tid, ''))
print('runs', len(runs))
f = lambda s: datetime.fromisoformat(s.replace('Z', '+00:00'))
def analyze(path):
    hb = []; calls = tools = cn = cr = 0; t0 = t1 = None; last = ''
    for line in open(path, errors='replace'):
        try: j = json.loads(line)
        except Exception: continue
        ts = j.get('timestamp')
        if ts: t0 = t0 or ts; t1 = ts
        m = j.get('message', {})
        if m.get('role') == 'assistant':
            calls += 1; u = m.get('usage', {}); cn += u.get('input_tokens', 0) + u.get('cache_creation_input_tokens', 0); cr += u.get('cache_read_input_tokens', 0)
            c = m.get('content')
            if isinstance(c, list):
                for b in c:
                    if b.get('type') == 'tool_use':
                        tools += 1
                        if b.get('name') in ('SubagentHandback', 'SendMessage'):
                            x = b['input'].get('message', '')
                            hb.append(x if isinstance(x, str) else json.dumps(x))
                    if b.get('type') == 'text' and b['text'].strip() and not hb: last = b['text']
    if hb: last = max(hb, key=len)
    return dict(calls=calls, tools=tools, new=cn, cr=cr, secs=int((f(t1) - f(t0)).total_seconds()) if t0 else 0, last=last)
out = []
for tid, r in runs.items():
    m = re.search(r'agentId: (\w+)', r['result']) or re.search(r'agent_id: ([\w-]+)@', r['result'])
    r['sub'] = None
    if m:
        key = m.group(1)
        cands = [p for p in agentfiles[r['proj']] if key in os.path.basename(p)]
        if cands: r['sub'] = analyze(cands[0])
    out.append(r)
out.sort(key=lambda x: (x['proj'], x['ts'] or ''))
json.dump(out, open(os.path.join(tmp, 'runs3.json'), 'w'))
c = collections.Counter((r['proj'], r['st'].split(':')[-1].replace('canon-', '').replace('lambda-', '').replace('vector-', '').replace('axiom-', ''), r['sub'] is not None) for r in out)
for k, v in sorted(c.items()): print(k, v)

